        check(self.drop_rate >= 0.0, "drop_rate >= 0.0")?;
        check(self.drop_rate <= 1.0, "drop_rate <= 1.0")?;
        get_int(params, "max_drop", &mut self.max_drop)?;
        get_double(params, "skip_drop", &mut self.skip_drop)?;
        check(self.skip_drop >= 0.0, "skip_drop >= 0.0")?;
        check(self.skip_drop <= 1.0, "skip_drop <= 1.0")?;
